/** Defaults for the Slack channel pack. */
export const SLACK_CHANNEL_ID = "slack";
export const SLACK_TYPING_MIN_GROWTH = 4;
export const SLACK_TYPING_MIN_INTERVAL_MS = 5_000;
/**
 * Slack `assistant.threads.setStatus` limits each `loading_messages[]`
 * entry to under 51 characters. `status` is often mirrored into that array,
 * so keep both at 50.
 */
export const SLACK_STATUS_MAX_LEN = 50;
export const SLACK_LOADING_MESSAGE_MAX_LEN = 50;
/** Slack `assistant.threads.setStatus` accepts at most 5 `loading_messages`. */
export const SLACK_LOADING_MESSAGES_MAX = 5;
export const SLACK_TITLE_MAX_LEN = 80;
/**
 * `markdown_text` (and so a streamed message, cards included) tops out near
 * 12k characters; past it Slack answers `msg_too_long`. Plain `text` allows
 * about 40k.
 */
export const SLACK_MARKDOWN_TEXT_MAX_LEN = 12_000;
/** Slack caps a `plan_update` (and `task_update`) chunk at 256 characters. */
export const SLACK_PLAN_TITLE_MAX_LEN = 256;
/** Slack `files.getUploadURLExternal` rejects `alt_txt` past this length. */
export const SLACK_FILE_ALT_TEXT_MAX_LEN = 1000;
/**
 * Caption posted with the file (`files.completeUploadExternal`
 * `initial_comment`). Same bound as a plain Slack message.
 */
export const SLACK_FILE_INITIAL_COMMENT_MAX_LEN = 40_000;
/** Rotating assistant status lines (Slack `loading_messages`). */
export const SLACK_DEFAULT_LOADING_MESSAGES = [
    "Thinking…",
    "Working on it…",
    "Almost there…",
];
/** Slack API errors that mean a feature is unavailable for this app. */
export const SLACK_UNSUPPORTED_ERRORS = new Set([
    "method_not_found",
    "not_allowed",
    "missing_scope",
    "not_enabled",
    "feature_not_enabled",
    "unknown_method",
]);
